output.arguments:
{"command":"cat <<'EOF' > /tmp/cb.hsh
let x = {
  echo hi | grep hi;
  echo hello >> out
  ls
}
EOF
./executable --ast /tmp/cb.hsh 2>&1
./executable --program /tmp/cb.hsh 2>&1

cat <<'EOF' > /tmp/cb2.hsh
let a = {
  echo hi | { cat; echo bye } | wc -l
}
EOF
./executable --ast /tmp/cb2.hsh 2>&1
./executable --program /tmp/cb2.hsh 2>&1

# capture semantics: $? Is for stdout capture but syntax ${ } does capture?
# earlier we saw ${ captures stdout into object with stdout stderr status?
# But for lexing we had ${ as token.
# And { as command block (un-captured?)
# And &{ as async?

cat <<'EOF' > /tmp/async.hsh
let a = &{
  sleep 1
}
a.join()
EOF
./executable --ast /tmp/async.hsh 2>&1
./executable --program /tmp/async.hsh 2>&1
./executable --lex /tmp/async.hsh 2>&1
cat <<'EOF' > /tmp/async2.hsh
let a = &{ echo hi }.join()
EOF
./executable --ast /tmp/async2.hsh 2>&1
./executable --program /tmp/async2.hsh 2>&1
./executable /tmp/async2.hsh 2>&1

# method calls
cat <<'EOF' > /tmp/method.hsh
let x = [1,2,3].len()
let y = "hi".len()
EOF
./executable --ast /tmp/method.hsh 2>&1
./executable --program /tmp/method.hsh 2>&1

# dict indexing syntax
cat <<'EOF' > /tmp/dict.hsh
let d = @[a: 1]
let v = d.a
let w = d["a"]
let e = d["a"].b
EOF
./executable --ast /tmp/dict.hsh 2>&1

# cmd expansions in quotes
cat <<'EOF' > /tmp/quot.hsh
let a = {
  echo "hi $HOME and ${x} is here";
  echo $HOME' and '"more";
  echo 'single quoted';
}
EOF
./executable --lex /tmp/quot.hsh 2>&1
./executable --ast /tmp/quot.hsh 2>&1

cat <<'EOF' > /tmp/quot2.hsh
let a = {
  echo 'don'\''t';
}
EOF
./executable --lex /tmp/quot2.hsh 2>&1
./executable --ast /tmp/quot2.hsh 2>&1

# expansion chaining ${{var}} tokenization:
# Earlier we saw ${{var}} tokenized as one token? Let's check.
cat <<'EOF' > /tmp/exp.hsh
{
  ls ~/;
  ls *~/;
  ls file-%.*;
  ls ~/*%file%*?;
  ls "*~/";
}
EOF
./executable --lex /tmp/exp.hsh 2>&1
./executable --ast /tmp/exp.hsh 2>&1
./executable --program /tmp/exp.hsh 2>&1

# command args: how '' handled?
cat <<'EOF' > /tmp/cmdarg.hsh
{
  echo $args' aren\'t '$boring" even when \$'$double' quoted";
}
EOF
./executable --lex /tmp/cmdarg.hsh 2>&1
./executable --ast /tmp/cmdarg.hsh 2>&1
./executable --program /tmp/cmdarg.hsh 2>&1

# Check for command-block redirects parsing exactly: earlier AST shows 2>1 etc.
# Let's see details on redirects:
# Appear as suffixes like 1>>"file", <"${file}", etc. How are they represented?
cat <<'EOF' > /tmp/redirect_detail.hsh
let c = {
  echo hi 2>1;
  echo hi 1>2;
  echo hi > file;
  echo hi >> file;
  echo hi < file;
  echo hi 2>>file;
  ls | grep hi 2>1 | wc
}
EOF
./executable --ast /tmp/redirect_detail.hsh 2>&1
./executable --program /tmp/redirect_detail.hsh 2>&1

"}

