# Simple Parser for AST

class Parser:
    def __init__(self, tokens):
        self.tokens=tokens
        self.pos=0
        self.indent=0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def advance(self):
        t=self.peek()
        if t:
            self.pos+=1
        return t

    def parse(self):
        stmts=[]
        while self.peek():
            stmt=self.parse_stmt()
            if stmt:
                stmts.append(stmt)
        return "\n".join(stmts)

    def parse_stmt(self):
        t=self.peek()
        if not t:
            return None
        if t.text=="let":
            self.advance()
            var=self.advance()
            var_name=var.text if var else "x"
            if self.peek() and self.peek().text=="=":
                self.advance()
                expr=self.parse_expr()
                return f"let {var_name} = {expr}"
            else:
                return f"let {var_name} = nil"
        if t.text=="if":
            self.advance()
            cond=self.parse_expr()
            # then
            if self.peek() and self.peek().text=="then":
                self.advance()
            then_body=[]
            while self.peek() and self.peek().text not in ("else","elseif","end"):
                then_body.append(self.parse_stmt())
            # handle elseif/else
            if self.peek() and self.peek().text=="elseif":
                # parse elseif as else if
                self.advance()
                econd=self.parse_expr()
                if self.peek() and self.peek().text=="then":
                    self.advance()
                ebody=[]
                while self.peek() and self.peek().text not in ("else","elseif","end"):
                    ebody.append(self.parse_stmt())
                # else?
                else_body=[]
                if self.peek() and self.peek().text=="else":
                    self.advance()
                    while self.peek() and self.peek().text!="end":
                        else_body.append(self.parse_stmt())
                if self.peek() and self.peek().text=="end":
                    self.advance()
                then_str="\n\t".join(then_body)
                ebody_str="\n\t".join(ebody)
                else_str="\n\t".join(else_body)
                # construct nested
                inner=f"if {econd} then\n\t{ebody_str}\nelse\n\t{else_str}\nend" if else_body else f"if {econd} then\n\t{ebody_str}\nend"
                return f"if {cond} then\n\t{then_str}\nelse\n\t{inner}\nend"
            elif self.peek() and self.peek().text=="else":
                self.advance()
                else_body=[]
                while self.peek() and self.peek().text!="end":
                    else_body.append(self.parse_stmt())
                if self.peek() and self.peek().text=="end":
                    self.advance()
                then_str="\n\t".join(then_body)
                else_str="\n\t".join(else_body)
                return f"if {cond} then\n\t{then_str}\nelse\n\t{else_str}\nend"
            else:
                if self.peek() and self.peek().text=="end":
                    self.advance()
                then_str="\n\t".join(then_body)
                return f"if {cond} then\n\t{then_str}\nend"
        if t.text=="for":
            self.advance()
            var=self.advance().text
            # in
            if self.peek() and self.peek().text=="in":
                self.advance()
            it=self.parse_expr()
            if self.peek() and self.peek().text=="do":
                self.advance()
            body=[]
            while self.peek() and self.peek().text!="end":
                body.append(self.parse_stmt())
            if self.peek() and self.peek().text=="end":
                self.advance()
            body_str="\n\t".join(body)
            return f"for {var} in {it} do\n\t{body_str}\nend"
        if t.text=="function":
            self.advance()
            # may have name
            name=None
            if self.peek() and self.peek().text!="(" and self.peek().text!="end":
                # check if next after is "(" => name
                if self.pos+1 < len(self.tokens) and self.tokens[self.pos+1].text=="(":
                    name=self.peek().text
                    self.advance()
            # params
            params=[]
            if self.peek() and self.peek().text=="(":
                self.advance()
                while self.peek() and self.peek().text!=")":
                    if self.peek().text==",":
                        self.advance()
                        continue
                    params.append(self.peek().text)
                    self.advance()
                if self.peek() and self.peek().text==")":
                    self.advance()
            body=[]
            while self.peek() and self.peek().text!="end":
                body.append(self.parse_stmt())
            if self.peek() and self.peek().text=="end":
                self.advance()
            body_str="\n\t".join(body)
            param_str=", ".join(params)
            if name:
                return f"let {name} = function({param_str})\n\t{body_str}\nend"
            else:
                return f"function({param_str})\n\t{body_str}\nend"
        if t.text=="return":
            self.advance()
            expr=self.parse_expr()
            return f"return {expr}" if expr else "return nil"
        if t.text=="break":
            self.advance()
            return "break"
        if t.text=="continue":
            self.advance()
            return "continue"
        # assignment with var = expr or expression statement
        # attempt to parse left expr then check =
        # save pos
        save=self.pos
        left=self.parse_expr()
        if self.peek() and self.peek().text=="=":
            self.advance()
            right=self.parse_expr()
            return f"{left} = {right}"
        else:
            self.pos=save
            expr=self.parse_expr()
            return expr

    def parse_expr(self):
        return self.parse_or()

    def parse_or(self):
        left=self.parse_and()
        while self.peek() and self.peek().text=="or":
            self.advance()
            right=self.parse_and()
            left=f"({left} or {right})"
        return left

    def parse_and(self):
        left=self.parse_unary()
        while self.peek() and self.peek().text=="and":
            self.advance()
            right=self.parse_unary()
            left=f"({left} and {right})"
        return left

    def parse_unary(self):
        if self.peek() and self.peek().text=="not":
            self.advance()
            e=self.parse_unary()
            return f"(not {e})"
        if self.peek() and self.peek().text=="-":
            self.advance()
            e=self.parse_unary()
            return f"(- {e})"
        return self.parse_bin()

    def parse_bin(self):
        left=self.parse_postfix()
        while self.peek() and self.peek().text in ("==","!=","<",">","<=",">=","+","-","*","/","%","++"):
            op=self.peek().text
            self.advance()
            right=self.parse_postfix()
            left=f"({left} {op} {right})"
        return left

    def parse_postfix(self, base=None):
        if base is None:
            base=self.parse_primary()
        while self.peek():
            if self.peek().text==".":
                self.advance()
                idt=self.advance().text if self.peek() else ""
                base=f"{base}.{idt}"
            elif self.peek().text=="[":
                self.advance()
                idx=self.parse_expr()
                if self.peek() and self.peek().text=="]":
                    self.advance()
                base=f"{base}[{idx}]"
            elif self.peek().text=="(":
                self.advance()
                args=[]
                while self.peek() and self.peek().text!=")":
                    if self.peek().text==",":
                        self.advance()
                        continue
                    args.append(self.parse_expr())
                if self.peek() and self.peek().text==")":
                    self.advance()
                base=f"{base}({', '.join(args)})"
            else:
                break
        return base

    def parse_primary(self):
        t=self.peek()
        if not t:
            return None
        if t.text in ("nil","true","false"):
            self.advance()
            return t.text
        if t.text[0].isdigit() or t.text[0]=='"' or t.text[0]=="'":
            self.advance()
            return t.text
        if t.text=="(":
            self.advance()
            e=self.parse_expr()
            if self.peek() and self.peek().text==")":
                self.advance()
            return f"({e})"
        if t.text=="[" or t.text=="@[":
            is_dict = (t.text=="@[")
            self.advance()
            elems=[]
            while self.peek() and self.peek().text!="]":
                if self.peek().text==",":
                    self.advance()
                    continue
                if is_dict:
                    key=self.advance().text
                    if self.peek() and self.peek().text==":":
                        self.advance()
                        val=self.parse_expr()
                        elems.append(f"{key}: {val}")
                else:
                    elems.append(self.parse_expr())
            if self.peek() and self.peek().text=="]":
                self.advance()
            if is_dict:
                return f"@[{', '.join(elems)}]"
            else:
                return f"[{', '.join(elems)}]"
        if t.text in ("{","${","&{"):
            typ=t.text
            self.advance()
            # collect until }
            inner=[]
            depth=1
            while self.peek():
                pt=self.peek()
                if pt.text in ("{","${","&{"):
                    depth+=1
                    inner.append(self.advance().text)
                elif pt.text=="}":
                    depth-=1
                    if depth==0:
                        self.advance()
                        break
                    inner.append(self.advance().text)
                else:
                    inner.append(self.advance().text)
            # for simplicity return block as { ... } with inner joined
            return f"{typ} {' '.join(inner)} }}"
        # identifier
        if re.match(r'^[A-Za-z_][A-Za-z0-9_]*$', t.text):
            self.advance()
            return t.text
        self.advance()
        return t.text

